function normalizeIssue (raw) {
  const obj = typeof raw === 'string' ? { message: raw } : (raw || {})
  const msg = obj.message || String(raw)
  const moduleIdent = obj.moduleIdentifier || obj.moduleName || ''
  const mpxDiagnostic = parseMpxDiagnosticHeader(msg)
  const file = mpxDiagnostic.file || extractFile(moduleIdent) || obj.file
  const loc = parseLoc(obj.loc) || mpxDiagnostic.loc
  const blockType = detectBlock(moduleIdent)
  const category = categorize({ message: msg, moduleIdent, blockType, name: obj.name })
  return {
    category,
    message: truncate(msg, 20),
    file,
    block: blockType,
    loc,
    raw: msg
  }
}

function truncate (msg, maxLines) {
  const lines = String(msg).split('\n')
  if (lines.length <= maxLines) return msg
  return lines.slice(0, maxLines).join('\n') + '\n...'
}

function parseMpxDiagnosticHeader (msg) {
  const match = String(msg).match(/^\[Mpx [^\]]+\]\[([^\]]+)\]:/)
  if (!match) return {}
  return parseFileLoc(match[1])
}

function parseFileLoc (raw) {
  const match = String(raw).match(/^(.*):(\d+):(\d+)$/)
  if (match) {
    return {
      file: match[1],
      loc: {
        line: +match[2],
        column: +match[3]
      }
    }
  }
  return {
    file: raw
  }
}

function extractFile (moduleIdent) {
  if (!moduleIdent) return undefined
  const m = moduleIdent.match(/([^!?\s]+\.mpx)(?:[?!]|$)/)
  if (m) return m[1]
  const segs = moduleIdent.split('!').filter(Boolean)
  const last = segs[segs.length - 1] || moduleIdent
  return last.split('?')[0]
}

function parseLoc (loc) {
  if (!loc) return undefined
  if (typeof loc === 'object' && loc.start) {
    return { line: loc.start.line, column: loc.start.column }
  }
  if (typeof loc === 'string') {
    const m = loc.match(/(\d+):(\d+)/)
    if (m) return { line: +m[1], column: +m[2] }
  }
  return undefined
}

function detectBlock (moduleIdent) {
  if (!moduleIdent) return undefined
  const q = moduleIdent.split('?')[1] || ''
  if (/[?&]type=styles?/.test('?' + q)) return 'style'
  if (/[?&]type=template/.test('?' + q)) return 'template'
  if (/[?&]type=script/.test('?' + q)) return 'script'
  if (/[?&]type=json/.test('?' + q)) return 'json'
# Skyline JSON 配置差异

本页记录微信 WebView / Skyline 双渲染模式下，应用与页面 JSON 相对基准的配置差异。JSON 区块语法与注册方式见 [JSON 基准](../base/json-reference.md)，编译插件、Worklet 与开发者工具配置见 [配置参考](./skyline-config-reference.md)。

## 目录

- [App 配置](#app-配置)
  - [app.json 顶层配置](#appjson-顶层配置)
  - [rendererOptions.skyline 配置项](#rendereroptionsskyline-配置项)
  - [应用配置示例](#应用配置示例)
- [页面配置](#页面配置)

## App 配置

页面与组件注册沿用 [App 配置基准](../base/json-reference.md#app-配置)。全局渲染配置位于应用 JSON，使用 `renderer`、`componentFramework` 与 `rendererOptions`；混合渲染项目按页面配置选择渲染模式，不能仅依据全局配置推断所有页面的实际 renderer。

### app.json 顶层配置

| 配置项 | 位置 | 类型 | 推荐值 / 示例 | 说明 |
| --- | --- | --- | --- | --- |
| `lazyCodeLoading` | `app.json` 顶层 | string | `"requiredComponents"` | 开启按需注入用到的组件代码，降低页面初始化时一次性注入的代码量，Skyline 必需，WebView 可按需 |
| `convertRpxToVw` | `app.json` 顶层 | boolean | 按需 | 基础库 3.3.0+；开启后会将 WebView rpx 计算逻辑对齐 Skyline（`rpx` 单位转换为 `vw` 单位），用于修复部分 `rpx` 精度问题 |

### rendererOptions.skyline 配置项

以下字段配置在 **应用 JSON 的 `rendererOptions.skyline`** 中：

| 配置项 | 类型 | 默认值 | 推荐值 | 说明 |
| --- | --- | --- | --- | --- |
| `defaultDisplayBlock` | boolean | false | true | 默认 `display: block`（对齐 WebView） |
| `defaultContentBox` | boolean | false | true | 默认 `box-sizing: content-box`（对齐 WebView） |
| `tagNameStyleIsolation` | string | "isolated" | "legacy" | 标签选择器全局匹配（对齐 WebView） |
| `enableScrollViewAutoSize` | boolean | false | true | scroll-view 自动撑开高度 |
| `keyframeStyleIsolation` | string | - | "legacy" | `@keyframes` 全局共享，避免迁移项目中动画关键帧作用域变化 |
| `disableABTest` | boolean | false | 按需 | 关闭 Skyline AB 实验，确保稳定性（非必要配置） |

> 前 5 项用于减少 WebView 与 Skyline 的默认行为差异，迁移项目应逐项检查。`disableABTest` 不是必填项，仅在需要排除灰度实验干扰、让页面全部使用 Skyline 时开启。

### 应用配置示例

应用 JSON 中对齐 WebView 默认行为的配置示例：

```json5
// 对齐 WebView
{
  "lazyCodeLoading": "requiredComponents",
  "rendererOptions": {
    "skyline": {
      "defaultDisplayBlock": true,
      "defaultContentBox": true,
      "tagNameStyleIsolation": "legacy",
      "enableScrollViewAutoSize": true,
      "keyframeStyleIsolation": "legacy"
    }
  }
}
```

> `defaultDisplayBlock` / `defaultContentBox` / `tagNameStyleIsolation` / `enableScrollViewAutoSize` / `keyframeStyleIsolation` 要写在 `rendererOptions.skyline` 内，不能放到 app.json 顶层。`lazyCodeLoading` 与 `convertRpxToVw` 属于顶层配置，其中 `convertRpxToVw` 和 `disableABTest` 根据项目需要选配。

## 页面配置

页面配置区块的写法见 [页面配置基准](../base/json-reference.md#页面配置)。Skyline 页面的渲染、导航与滚动配置如下：

| 配置项 | Skyline 配置 | 说明 |
| --- | --- | --- |
| `renderer` | `'skyline'` | 选择 Skyline 渲染；需要 WebView 的页面使用 `'webview'`。 |
| `componentFramework` | `'glass-easel'` | 使用 glass-easel 组件框架。 |
## 默认值差异与配置影响

以下对比未显式声明样式时的表现；项目已有 WXSS、组件默认样式和 Skyline 配置均可能覆盖这些基线。配置的完整接入方式见 [rendererOptions.skyline](skyline-json-reference.md#rendereroptionsskyline-配置项)。

| 属性 | WebView 基线 / 场景 | Skyline 默认值（未开启兼容配置） | 配置影响与迁移处理 |
| --- | --- | --- | --- |
| `display` | 普通 `view` 按块级布局 | `flex` | `defaultDisplayBlock: true` 后为 `block`；特殊组件仍核对自身布局 |
| `position` | 普通流中为 `static` | `relative` | 需要静态定位时显式声明 `static` |
| `box-sizing` | 常规 CSS 基线为 `content-box` | `border-box` | `defaultContentBox: true` 后为 `content-box` |
| `flex-direction` | Flex 容器默认 `row` | `column` | `defaultDisplayBlock: true` 时为 `row` |
| `align-items` | 默认 `normal`，Flex 场景通常表现为拉伸 | `stretch` | `defaultDisplayBlock: true` 时为 `normal` |
| `mask-repeat` | 默认为 `repeat` | `no-repeat` | 需要平铺时显式声明 `repeat` |
| `mask-position-x` / `mask-position-y` | [CSS 遮罩初始位置](https://www.w3.org/TR/css-masking-1/#the-mask-position)为 `0% 0%` | 默认 `center` | 不依赖默认定位；按原设计显式设置 `mask-position` |

> `text-align: start` 不作为独立默认值差异：两种渲染模式均需结合文本方向理解。若业务要求固定物理方向，显式设置 `left` / `right`；Skyline 的 `direction` 限制见 [文本与字体差异](#文本与字体差异)。

## 选择器差异

| 选择器 / 写法 | WebView 表现 | Skyline 差异 | 迁移处理 |
| --- | --- | --- | --- |
| `*` | 通配匹配 | **不支持** | 使用页面根类或组件类 |
| `[attr]` / `[attr=value]` | 按属性匹配 | **不支持** | 用 `wx:class` 表达动态状态，再使用类选择器 |
| `::before` / `::after` 以外的伪元素 | 随 WebView 支持情况可用 | **取值受限**：仅使用已支持的 `::before` / `::after` | 其他伪元素改为真实节点 |
| `:active` | 可表达按压状态 | **不支持** | 使用组件的 `hover-class` / `hover-stay-time` |

> 其他可用选择器：
>
> 1. `:first-child` / `:last-child` 可用；
> 2. 兄弟选择器 `a ~ b` / `a + b` 及 `:not` / `:only-child` / `:empty` 微信 8.0.49+ 可用；
> 3. `:nth-child` 微信 8.0.50+ 可用。

